			// irradiance are read, so both lookups take the halved variants
			// (same values, see GetSkyTransmittance / GetSkyIrradianceLum).
			sky_transmittance = GetSkyTransmittance(
				atm, transmittanceTex, pos - ctx.earthCenter, ctx.sunDir);
			skyIrradiance = GetSkyIrradianceLum(atm, irradianceTex,
				pos - ctx.earthCenter, normalize(pos - ctx.earthCenter), ctx.sunDir);
			sunLight = sky_transmittance * atm.sun_spectral_radiance_to_luminance;
			// night
			skyIrradiance = max(vec3f(10.0), skyIrradiance);
			sunLight = max(vec3f(100.0), sunLight);

			let vis = ComputeLightVisibility(ctx, baseNoise, noiseSamp, detailNoise,
				currentWeatherMap, weatherSamp, nextWeatherMap, pos, ctx.sunDir,
				phases);

			let sampleSigmaS = ctx.sigmaS * density;
			let sampleSigmaT = max(ctx.sigmaT * density, CLOUD_EPS);

			let powder = exp(-density * sampleSigmaT);
