	let l = 1.0 - g;
	let i1 = min(g.xyz, l.zxy);
	let i2 = max(g.xyz, l.zxy);

	let x1 = x0 - i1 + C.xxx;
	let x2 = x0 - i2 + C.yyy;
	let x3 = x0 - D.yyy;

