	let dx33 = Pfx + jitter * ox33;
	let dy33 = Pfy.z + jitter * oy33;
	let dz33 = Pfz.z + jitter * oz33;

	let d11 = dx11 * dx11 + dy11 * dy11 + dz11 * dz11;
