	let dy31 = Pfy.z + jitter * oy31;
	let dz31 = Pfz.x + jitter * oz31;

	let dx32 = Pfx + jitter * ox32;
	let dy32 = Pfy.z + jitter * oy32;
	let dz32 = Pfz.y + jitter * oz32;

